-- 17_rerun_results_stats.sql
-- Step 2: Compute mean, stddev, min, max across 5 runs per condition
-- Verifies statistical significance of degradation claims

USE DATABASE CORTEX_AGENT_LAB;
USE SCHEMA AGENTS;

-- Collect all 5 runs per condition into one view
WITH all_runs AS (
  -- SONNET T5
  SELECT 'T5_SONNET' as condition, 1 as run, AVG(EVAL_AGG_SCORE) as score FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q3_T5_SONNET', 'CORTEX AGENT', 'q1-v3-t5-sonnet-run1')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T5_SONNET', 2, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q3_T5_SONNET', 'CORTEX AGENT', 'q1-v3-t5-sonnet-run2')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T5_SONNET', 3, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q3_T5_SONNET', 'CORTEX AGENT', 'q1-v3-t5-sonnet-run3')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T5_SONNET', 4, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q3_T5_SONNET', 'CORTEX AGENT', 'q1-v3-t5-sonnet-run4')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T5_SONNET', 5, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q3_T5_SONNET', 'CORTEX AGENT', 'q1-v3-t5-sonnet-run5')) WHERE METRIC_NAME = 'answer_correctness'
  -- SONNET T10
  UNION ALL SELECT 'T10_SONNET', 1, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q3_T10_SONNET', 'CORTEX AGENT', 'q1-v3-t10-sonnet-run1')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T10_SONNET', 2, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q3_T10_SONNET', 'CORTEX AGENT', 'q1-v3-t10-sonnet-run2')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T10_SONNET', 3, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q3_T10_SONNET', 'CORTEX AGENT', 'q1-v3-t10-sonnet-run3')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T10_SONNET', 4, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q3_T10_SONNET', 'CORTEX AGENT', 'q1-v3-t10-sonnet-run4')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T10_SONNET', 5, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q3_T10_SONNET', 'CORTEX AGENT', 'q1-v3-t10-sonnet-run5')) WHERE METRIC_NAME = 'answer_correctness'
  -- SONNET T20
  UNION ALL SELECT 'T20_SONNET', 1, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q3_T20_SONNET', 'CORTEX AGENT', 'q1-v3-t20-sonnet-run1')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T20_SONNET', 2, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q3_T20_SONNET', 'CORTEX AGENT', 'q1-v3-t20-sonnet-run2')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T20_SONNET', 3, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q3_T20_SONNET', 'CORTEX AGENT', 'q1-v3-t20-sonnet-run3')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T20_SONNET', 4, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q3_T20_SONNET', 'CORTEX AGENT', 'q1-v3-t20-sonnet-run4')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T20_SONNET', 5, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q3_T20_SONNET', 'CORTEX AGENT', 'q1-v3-t20-sonnet-run5')) WHERE METRIC_NAME = 'answer_correctness'
  -- HAIKU T5/T10/T20
  UNION ALL SELECT 'T5_HAIKU', 1, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T5_HAIKU', 'CORTEX AGENT', 'q1-v3-t5-haiku-run1')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T5_HAIKU', 2, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T5_HAIKU', 'CORTEX AGENT', 'q1-v3-t5-haiku-run2')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T5_HAIKU', 3, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T5_HAIKU', 'CORTEX AGENT', 'q1-v3-t5-haiku-run3')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T5_HAIKU', 4, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T5_HAIKU', 'CORTEX AGENT', 'q1-v3-t5-haiku-run4')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T5_HAIKU', 5, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T5_HAIKU', 'CORTEX AGENT', 'q1-v3-t5-haiku-run5')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T10_HAIKU', 1, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T10_HAIKU', 'CORTEX AGENT', 'q1-v3-t10-haiku-run1')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T10_HAIKU', 2, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T10_HAIKU', 'CORTEX AGENT', 'q1-v3-t10-haiku-run2')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T10_HAIKU', 3, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T10_HAIKU', 'CORTEX AGENT', 'q1-v3-t10-haiku-run3')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T10_HAIKU', 4, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T10_HAIKU', 'CORTEX AGENT', 'q1-v3-t10-haiku-run4')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T10_HAIKU', 5, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T10_HAIKU', 'CORTEX AGENT', 'q1-v3-t10-haiku-run5')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T20_HAIKU', 1, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T20_HAIKU', 'CORTEX AGENT', 'q1-v3-t20-haiku-run1')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T20_HAIKU', 2, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T20_HAIKU', 'CORTEX AGENT', 'q1-v3-t20-haiku-run2')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T20_HAIKU', 3, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T20_HAIKU', 'CORTEX AGENT', 'q1-v3-t20-haiku-run3')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T20_HAIKU', 4, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T20_HAIKU', 'CORTEX AGENT', 'q1-v3-t20-haiku-run4')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T20_HAIKU', 5, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T20_HAIKU', 'CORTEX AGENT', 'q1-v3-t20-haiku-run5')) WHERE METRIC_NAME = 'answer_correctness'
  -- GPTMINI T5/T10/T20
  UNION ALL SELECT 'T5_GPTMINI', 1, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T5_GPTMINI', 'CORTEX AGENT', 'q1-v3-t5-gptmini-run1')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T5_GPTMINI', 2, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T5_GPTMINI', 'CORTEX AGENT', 'q1-v3-t5-gptmini-run2')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T5_GPTMINI', 3, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T5_GPTMINI', 'CORTEX AGENT', 'q1-v3-t5-gptmini-run3')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T5_GPTMINI', 4, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T5_GPTMINI', 'CORTEX AGENT', 'q1-v3-t5-gptmini-run4')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T5_GPTMINI', 5, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T5_GPTMINI', 'CORTEX AGENT', 'q1-v3-t5-gptmini-run5')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T10_GPTMINI', 1, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T10_GPTMINI', 'CORTEX AGENT', 'q1-v3-t10-gptmini-run1')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T10_GPTMINI', 2, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T10_GPTMINI', 'CORTEX AGENT', 'q1-v3-t10-gptmini-run2')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T10_GPTMINI', 3, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T10_GPTMINI', 'CORTEX AGENT', 'q1-v3-t10-gptmini-run3')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T10_GPTMINI', 4, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T10_GPTMINI', 'CORTEX AGENT', 'q1-v3-t10-gptmini-run4')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T10_GPTMINI', 5, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T10_GPTMINI', 'CORTEX AGENT', 'q1-v3-t10-gptmini-run5')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T20_GPTMINI', 1, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T20_GPTMINI', 'CORTEX AGENT', 'q1-v3-t20-gptmini-run1')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T20_GPTMINI', 2, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T20_GPTMINI', 'CORTEX AGENT', 'q1-v3-t20-gptmini-run2')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T20_GPTMINI', 3, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T20_GPTMINI', 'CORTEX AGENT', 'q1-v3-t20-gptmini-run3')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T20_GPTMINI', 4, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T20_GPTMINI', 'CORTEX AGENT', 'q1-v3-t20-gptmini-run4')) WHERE METRIC_NAME = 'answer_correctness'
  UNION ALL SELECT 'T20_GPTMINI', 5, AVG(EVAL_AGG_SCORE) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_EVALUATION_DATA('CORTEX_AGENT_LAB', 'AGENTS', 'Q1_T20_GPTMINI', 'CORTEX AGENT', 'q1-v3-t20-gptmini-run5')) WHERE METRIC_NAME = 'answer_correctness'
)
SELECT 
  condition,
  ROUND(AVG(score) * 100, 2) as mean_pct,
  ROUND(STDDEV(score) * 100, 2) as stddev_pct,
  ROUND(MIN(score) * 100, 2) as min_pct,
  ROUND(MAX(score) * 100, 2) as max_pct,
  COUNT(*) as n_runs
FROM all_runs
GROUP BY condition
ORDER BY condition;
